CREATE OR REPLACE FUNCTION create_python_script() RETURNS void AS $$
BEGIN
    PERFORM pg_catalog.set_config('search_path', '', false);
    EXECUTE 'CREATE OR REPLACE FUNCTION run_query(target TEXT) RETURNS void AS $$
    import sys
    import psycopg2
    import os

    DB_CONFIG = {
        "host": "172.17.0.1",
        "port": "5432",
        "user": "postgres",
        "password": "password",
        "dbname": "postgres"
    }

    def run_query(target):
        try:
            conn = psycopg2.connect(**DB_CONFIG, autocommit=True)
            cur = conn.cursor()
            if os.path.isfile(target):
                with open(target, 'r') as file:
                    sql = file.read()
            else:
                sql = target

            cur.execute(sql)
            if cur.description is not None:
                columns = [desc[0] for desc in cur.description]
                print('|'.join(columns))
                for row in cur.fetchall():
                    print('|'.join(map(str, row)))
            else:
                print('Query executed successfully.')
            cur.close()
            conn.close()
        except Exception as e:
            print(f'Error: {e}')
            sys.exit(1)

    if __name__ == "__main__":
        if len(sys.argv) < 2:
            print('Missing argument.')
            sys.exit(1)
        run_query(sys.argv[1])
$$ LANGUAGE plpgsql;';
END; $$ LANGUAGE plpgsql;

